sources=[('HHS HIPAA Privacy Rule','https://www.hhs.gov/hipaa/for-professionals/privacy/index.html'),('Centers for Medicare and Medicaid Services','https://www.cms.gov/'),('NIST Cybersecurity Framework','https://www.nist.gov/cyberframework'),('Federal Trade Commission','https://www.ftc.gov/'),('U.S. Small Business Administration','https://www.sba.gov/'),('U.S. Department of Labor','https://www.dol.gov/')]
def blog(slug,title,focus,owner,src,stop):
 body=[f'## Why the {focus} needs its own control',f'A {focus} case without a named owner can move through the billing queue while nobody can say what was checked. The {owner} keeps the financial, coding, privacy, and patient-commitment decisions. The assistant may organize the record, compare approved sources, and route exceptions.',f'The approved input is {src}. Keep evidence in the billing system; a parallel tracker becomes stale after the next remittance. Record the source date and next action without copying unnecessary health or financial detail into chat.',f'## What the {focus} record must show','The record connects the account, source document, reviewer, decision owner, changed field, and completion evidence. Missing and conflicting values remain visible. A sent message or checked box proves activity, not an approved claim or patient balance change.',f'## Where the VA’s work stops',f'The assistant may collect, compare, index, and prepare questions. The {owner} decides coverage, coding, refunds, and patient commitments. The stop condition is: {stop}.',f'## The daily {focus} routine','Start with the oldest item and the nearest payer or patient deadline. Open the source, confirm the account and version, record the last verified fact, and leave a named next action. At handoff, name what moved, what is waiting, who owns the next check, and which evidence is missing.',f'## Exceptions that should stop the case','Stop on missing identity, conflicting records, an expired payer rule, a privacy question, a clinical or coding question, or a request outside the assigned scope. The note should say what was requested, what the source shows, and who must decide.',f'## How to verify and close','Close only when the billing system, payer record, or patient-visible statement shows the approved result. A phone call can start the check, but the dated record is the evidence. A close note says what was checked, who approved it, what changed, and what would reopen the case.',f'## The monthly {focus} review','Sample normal, exception, and reopened records against the same written rule. End with one process change, one owner, and one check date.']
 return {'slug':slug,'title':title,'description':f'A source-bounded outsourced billing operations guide for billing and revenue cycle teams, focused on {focus} and bounded by honest evidence.','published':DATE,'featuredImage':f'/daily02/outsourcedbillingservices/{slug}.png','body':body}
def research_item(slug,title,focus,owner,unit,example):
 heads=['Research question and scope','Population and unit of analysis','Definitions that make the measure reproducible','Evidence standard and data dictionary','Sampling and collection','Analysis and reporting','Limitations and sources of error','Review cadence and next action']
 paras=[f'This protocol asks how {focus} can be described from the billing record, using one defined population and one observation window. The {owner} owns the decision.',f'The unit is one {unit}, from opening event through recorded close. Keep linked revisions separate and record the source date and owner.',f'Define the opening event, closing event, pause rule, and missing-evidence rule before collecting {focus} data. Report eligible count, sample, exceptions, and unresolved items.',f'Record the source, observation time, field supported, reviewer, and decision owner. Keep restricted patient and financial data in the approved system. Example: {example}',f'Sample routine, exception, and reopened records. Preserve the original observation when a definition changes and label the new rule for later cases.',f'Report observation separately from interpretation. Show the oldest open item and missing fields, not only the completion rate. Name the next decision and its owner.',f'The cited public sources frame billing privacy, security, and recordkeeping practice in general terms; they do not provide a local result or coverage advice for a specific claim.',f'Review the result on a fixed date and end with one process change, one owner, and one check date.']
 body=[]
 for h,p in zip(heads,paras): body += [f'## {h}',p]
 body += ['## Sources']+[f'- [{n}]({u}) — checked {DISPLAY}.' for n,u in sources]
 return {'slug':slug,'title':title,'excerpt':f'A repeatable measurement protocol for {focus} in outsourced billing operations, with definitions, sampling, limits, and reporting.','published':DATE,'datePublished':DATE,'updated':DATE,'featuredImage':f'/daily02/outsourcedbillingservices/{slug}.png','body':body}
bl=[blog(*b) for b in blogs]; rs=[research_item(*r) for r in research]
blog_ts="export const nov02BlogBatch="+json.dumps(bl,indent=2,ensure_ascii=False)+";\nexport const nov02BlogSlugs=nov02BlogBatch.map((post)=>post.slug);\n"
