 t=t.replace('const oct28Paths = oct28BlogSlugs.map((slug) => `/blog/${slug}`);','const oct28Paths = oct28BlogSlugs.map((slug) => `/blog/${slug}`);\n  const nov02Paths = nov02BlogSlugs.map((slug) => `/blog/${slug}`);')
 t=t.replace('...oct22Paths, ...oct13Paths, ...oct25Paths, ...oct26Paths, ...oct28Paths, ...oct27Paths,','...oct22Paths, ...oct13Paths, ...oct25Paths, ...oct26Paths, ...oct28Paths, ...nov02Paths, ...oct27Paths,')
